(function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function money(amount,currency){
 const code=String(currency||'AED').toUpperCase(),format=new Intl.NumberFormat('en',{style:'currency',currency:code});
 const digits=['ISK','UGX'].includes(code)?2:format.resolvedOptions().maximumFractionDigits;
 return format.format(amount/10**digits);
}
function render(data,sample=false){
 const receipt=data.receipt,refunded=receipt.refundedAmount||0;
 const title=sample?'Your payment receipt, brought to life.':data.status==='Paid'?'Payment confirmed. You’re ready to learn.':'Your payment record.';
 const detail=sample?'Preview the animation that plays after a payment is confirmed. This sample does not create an order, charge or learning access.':data.status==='Paid'?'Your receipt is ready. Continue to the pathway included in your purchase.':data.status==='Partially refunded'?'A partial refund has been recorded. Your original receipt and the refunded amount are shown below.':'This order is '+data.status.toLowerCase()+'. The receipt preserves the original payment record; the order status determines current access.';
 const amount=sample?'—':money(receipt.amount,receipt.currency),date=sample?'After payment confirmation':new Date(receipt.confirmedAt).toLocaleString('en',{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC';
 return `<div class="page-head"><div><h1>${title}</h1><p>${detail}</p></div><a class="btn" href="#shop">Back to access & receipts</a></div>
 <ol class="checkout-steps" aria-label="Purchase progress"><li class="done"><span>1</span>Secure checkout</li><li class="done"><span>2</span>${sample?'Payment confirmation':'Payment recorded'}</li><li class="current"><span>3</span>Receipt & learning</li></ol>
 ${sample?'<div class="notice">ANIMATION PREVIEW · SAMPLE RECEIPT · NO PAYMENT MADE</div>':''}
 <div class="receipt-layout"><section class="receipt-visual" aria-label="Receipt printer"><div class="receipt-printer" data-receipt-machine="${esc(receipt.number)}">
 <div class="printer-housing" aria-hidden="true"><span class="printer-brand">DIGITALBURJ</span><span class="printer-indicator"></span><div class="printer-slot"></div></div>
 <div class="paper-window"><article class="receipt-paper"><img src="brand/academy-lockup.webp" alt="DigitalBurj Academy"><p class="receipt-label">${sample?'SAMPLE · NOT A PAYMENT RECORD':'PAYMENT RECEIPT'}</p><h2>${sample?'Learning pathway':esc(receipt.title)}</h2><dl><div><dt>Reference</dt><dd>${sample?'SAMPLE':esc(receipt.number)}</dd></div><div><dt>Confirmed</dt><dd>${esc(date)}</dd></div><div><dt>Current status</dt><dd>${sample?'Demonstration only':esc(data.status)}</dd></div></dl><div class="receipt-total"><span>${sample?'Payment amount':'Amount paid'}</span><strong>${esc(amount)}</strong></div>${refunded?`<div class="receipt-refund"><span>Refund recorded</span><b>${esc(money(refunded,receipt.currency))}</b></div>`:''}<p class="receipt-footnote">${sample?'An actual receipt uses your confirmed order details.':'Payment acknowledgement. This is not a tax invoice.'}</p><div class="receipt-tear" aria-hidden="true"></div></article></div></div><p class="receipt-animation-status" role="status">${sample?'Sample receipt ready.':'Payment receipt ready.'}</p></section>
 <aside class="receipt-next panel"><span class="label">${sample?'What happens next':'Your next step'}</span><h2>${sample?'From purchase to progress.':data.activeCourseIds.length?'Start with the first project.':'Check your learning access.'}</h2><ol class="next-steps"><li>Payment is confirmed securely.</li><li>Your receipt is saved with your order.</li><li>Purchased pathway access becomes available.</li><li>Learn, build evidence and submit for assessment.</li></ol><div class="receipt-actions">${sample?'<a class="btn primary" href="#paths">Explore learning pathways</a>':data.activeCourseIds.length?data.activeCourseIds.map(id=>`<a class="btn primary" href="#path/${encodeURIComponent(id)}">Open ${esc(data.pathNames?.[id]||id)} →</a>`).join(''):'<a class="btn primary" href="#shop">Review access options</a>'}<button class="btn" data-receipt-action="replay">Replay receipt animation</button>${sample?'':'<button class="btn" data-receipt-action="print">Print / save receipt PDF</button><button class="text-link" data-receipt-action="download">Download receipt record</button>'}</div><p class="small muted">${sample?'Actual payment confirmation triggers the animation automatically. Reduced-motion preferences are respected.':'Purchasing grants learning access. Certificates require completed projects, qualified review and independent verification.'}</p></aside></div>`;
}
let current=null;
function animate(){const machine=document.querySelector('[data-receipt-machine]');if(!machine)return;machine.classList.remove('is-printing');void machine.offsetWidth;machine.classList.add('is-printing')}
function mount(data,sample=false){current={data,sample};const machine=document.querySelector('[data-receipt-machine]');if(!machine)return;const key='dba-receipt-seen-'+data.receipt.number;let seen=false;try{seen=sessionStorage.getItem(key)==='1';sessionStorage.setItem(key,'1')}catch{}if(sample||!seen)animate()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-receipt-action]');if(!b||!current)return;const a=b.dataset.receiptAction;if(a==='replay')animate();if(a==='print'&&!current.sample)window.print();if(a==='download'&&!current.sample)window.AcademyStudio.download('DigitalBurj-'+current.data.receipt.number+'.json',JSON.stringify({receipt:current.data.receipt,currentOrderStatus:current.data.status,exportedAt:new Date().toISOString()},null,2),'application/json')});
window.AcademyReceipt={render,mount,money};
})();
